108	/**
109	 * Appended to every printed row line that relied on an asserted-complete
110	 * input. Fixed and greppable: a reader can tell asserted from proven without
111	 * the FR. A row reading only measured inputs never carries it.
112	 */
113	export const COMPLETENESS_ASSERTED_MARKER = "[completeness asserted by the session, not proven by the tracker]";
