143	/** One parsed input, or the reason it could not be read. */
144	type Input<T> = { ok: true; value: T } | { ok: false; reason: string };
145	
146	function failed(reason: string): { ok: false; reason: string } {
147	  return { ok: false, reason };
148	}
149	
150	function isObject(v: unknown): v is Record<string, unknown> {
151	  return v !== null && typeof v === "object" && !Array.isArray(v);
152	}
153	
154	/** The first line of a thrown value's message. */
155	function firstLine(e: unknown): string {
156	  return (e instanceof Error ? e.message : String(e)).split("\n")[0]!;
157	}
158	
159	/** A filesystem error's code (`ENOENT`, …), else its message. */
160	function errCode(e: unknown): string {
161	  return (e as NodeJS.ErrnoException).code ?? (e as Error).message;
162	}
163	
164	/** Read and JSON-parse the file at `path`; `label` opens every failure reason. */
165	function readJsonAt(label: string, path: string): Input<unknown> {
166	  let text: string;
167	  try {
168	    text = readFileSync(path, "utf-8");
169	  } catch (e) {
170	    return failed(`${label} cannot be read (${errCode(e)})`);
171	  }
172	  try {
173	    return { ok: true, value: JSON.parse(text) };
174	  } catch (e) {
175	    return failed(`${label} is not JSON (${(e as Error).message})`);
176	  }
177	}
178	
179	/** Read and JSON-parse one listing file named by `flag`. */
180	function readJson(flag: string, path: string | undefined): Input<unknown> {
181	  if (path === undefined) return failed(`${flag} was not passed`);
182	  return readJsonAt(`${flag} ${path}`, path);
183	}
184	
185	/** A parsed `{ <arrayKey>: [{ <field>: string }] }` listing, reduced to that field's values. */
186	function namedRows(label: string, v: unknown, arrayKey: string, field: string): Input<string[]> {
187	  if (!isObject(v) || !Array.isArray(v[arrayKey])) return failed(`${label} has no \`${arrayKey}\` array`);
188	  const out: string[] = [];
189	  for (const row of v[arrayKey] as unknown[]) {
190	    if (!isObject(row) || typeof row[field] !== "string") {
191	      return failed(`${label} carries a \`${arrayKey}\` row with no string \`${field}\``);
192	    }
193	    out.push(row[field] as string);
194	  }
195	  return { ok: true, value: out };
196	}
197	
198	/**
199	 * A hand-assembled Jira listing (no Atlassian MCP tool lists a project's
200	 * statuses or labels) must itself CLAIM `isLast: true`; a missing claim
201	 * cannot prove absence. The claim is the session's assertion, never the
202	 * tracker's proof — the row that relies on it carries the marker.
203	 */
204	function notLastPage(label: string, v: Record<string, unknown>): Input<never> | undefined {
205	  return v.isLast === true ? undefined : failed(`${label} is not the last page (isLast is not true)`);
206	}
207	
208	/**
209	 * One measured list answer (`readCompleteList`, tracker_answer.ts), proven
210	 * whole by the tracker or refused, reduced to each row's `field`.
211	 */
212	function readMeasuredList(flag: string, path: string | undefined, tool: CompleteListTool, field: string): Input<string[]> {
213	  const json = readJson(flag, path);
214	  if (!json.ok) return json;
215	  const label = `${flag} ${path}`;
216	  const read = readCompleteList(tool, json.value);
217	  if (!read.ok) return failed(`${label} is not a ${tool.split(":")[1]} answer: ${read.reason}`);
218	  if (!read.complete) return failed(`${label} does not prove it holds the whole list`);
219	  return namedRows(label, { rows: read.items }, "rows", field);
220	}
221	
222	/**
223	 * `--projects`, both measured and read by the shared reader
224	 * (`tracker_answer.ts`): Jira the getVisibleJiraProjects answer `{ …, isLast,
225	 * values: [{ key }] }`, proven whole by `isLast`; Linear the list_projects
226	 * answer `{ projects: [{ name }], hasNextPage, cursor? }`, proven its last page.
227	 */
228	function readProjects(args: RepointArgs): Input<string[]> {
229	  if (args.mode === "linear") {
230	    const json = readJson("--projects", args.projects);
231	    if (!json.ok) return json;
232	    const label = `--projects ${args.projects}`;
233	    const read = readTrackerPage("linear", json.value, "projects");
234	    if (!read.ok) return failed(`${label} is not a list_projects answer: ${read.reason}`);
235	    if (!read.page.last) return failed(`${label} is not the last page (hasNextPage is true)`);
236	    return namedRows(label, { projects: read.page.items }, "projects", "name");
237	  }
238	  return readMeasuredList("--projects", args.projects, "jira:getVisibleJiraProjects", "key");
239	}
