241	/**
242	 * `--labels` (Jira): `{ values: ["label", …], isLast: true }`, hand-assembled —
243	 * no Atlassian MCP tool lists a project's labels, so its completeness is the
244	 * session's assertion (row 6 carries COMPLETENESS_ASSERTED_MARKER).
245	 */
246	function readLabels(path: string | undefined): Input<string[]> {
247	  const json = readJson("--labels", path);
248	  if (!json.ok) return json;
249	  const label = `--labels ${path}`;
250	  const v = json.value;
251	  if (!isObject(v) || !Array.isArray(v.values)) return failed(`${label} has no \`values\` array`);
252	  const partial = notLastPage(label, v);
253	  if (partial !== undefined) return partial;
254	  if (!(v.values as unknown[]).every((l) => typeof l === "string")) {
255	    return failed(`${label} carries a non-string label`);
256	  }
257	  return { ok: true, value: v.values as string[] };
258	}
