260	/** `--containers`: parsed by the one listing reader STE-608 ships. */
261	function readContainers(args: RepointArgs): Input<ReadListing> {
262	  if (args.containers === undefined) return failed("--containers was not passed");
263	  try {
264	    return {
265	      ok: true,
266	      value: readListingFile({ mode: args.mode, project: args.newProject, listingFile: args.containers }),
267	    };
268	  } catch (e) {
269	    return failed(firstLine(e));
270	  }
271	}
