273	/** `.mcp.json` at `root`: its `mcpServers` map. */
274	function readMcpServers(root: string): Input<Record<string, unknown>> {
275	  const path = join(root, ".mcp.json");
276	  const json = readJsonAt(path, path);
277	  if (!json.ok) return json;
278	  const v = json.value;
279	  if (!isObject(v) || !isObject(v.mcpServers)) return failed(`${path} has no \`mcpServers\` map`);
280	  return { ok: true, value: v.mcpServers };
281	}
