283	/** `specs/tracker-config.yaml` statuses, through the one config reader. Absent refuses. */
284	function readConfigStatuses(root: string): Input<string[]> {
285	  const specs = join(root, "specs");
286	  if (!existsSync(join(specs, "tracker-config.yaml"))) return failed("specs/tracker-config.yaml is absent");
287	  try {
288	    return { ok: true, value: readTrackerConfig(specs)!.statuses };
289	  } catch (e) {
