294	/**
295	 * A refusal about what a PEER repository declares.
296	 *
297	 * MEASURED LIVE (2026-09-23): row 3 refused with `--peer <A> declares
298	 * jira_issue_type (none), not Task`. It named a disagreement and a file, and
299	 * named no action the running session could legally take — so the session took
300	 * the illegal one and edited the peer's CLAUDE.md. A guard's refusal INDUCED
301	 * the cross-repository write it exists to make visible.
302	 *
303	 * Every such reason is built here, so the six sites cannot drift apart: each
304	 * names what the peer declares, an action available to this repository's
305	 * operator alone, and the one action that is always available — dropping the
306	 * flag. `--peer` is an assertion about a repository this run does not own.
307	 */
308	function peerRefusal(path: string, observed: string, remedy: string): string {
309	  return `--peer ${path} ${observed}. ${remedy}; do not edit ${path} from here — a peer's CLAUDE.md belongs to that repository's operator — or re-run without --peer ${path}, which checks this repository alone.`;
310	}
311	
312	/**
313	 * A refusal about the `--peer` FLAG rather than about what the peer declares.
314	 * It carries the always-available action and deliberately not the do-not-edit
315	 * clause: there is no declaration in dispute, and on a path that does not
316	 * exist the clause would be noise.
317	 */
318	const peerFlagRefusal = (path: string, observed: string): string =>
319	  `--peer ${path} ${observed}; name an existing peer root, or re-run without --peer ${path}.`;
320	
321	/** A peer root: an existing directory holding a CLAUDE.md. */
322	function readPeer(path: string): Input<string> {
323	  let isDir = false;
324	  try {
325	    isDir = statSync(path).isDirectory();
326	  } catch {
327	    return failed(peerFlagRefusal(path, "does not exist"));
328	  }
329	  if (!isDir) return failed(peerFlagRefusal(path, "is not a directory"));
330	  if (!existsSync(join(path, "CLAUDE.md"))) return failed(peerFlagRefusal(path, "has no CLAUDE.md, so its binding cannot be checked"));
331	  return { ok: true, value: path };
332	}
333	
334	/** The trimmed value of `key:` in `text`'s tracker sub-section, through `locateSubsection`. */
335	function subsectionValueIn(text: string, adapter: WorkspaceAdapterKey, key: string): string | undefined {
336	  const sub = locateSubsection(text.replace(/\r\n?/g, "\n").split("\n"), adapter) ?? [];
337	  for (const line of sub) {
338	    const m = /^([a-z_][a-z0-9_]*)\s*:\s*(.*)$/.exec(line);
339	    if (m && m[1] === key && m[2]!.trim().length > 0) return m[2]!.trim();
340	  }
341	  return undefined;
342	}
343	
344	/** The trimmed value of `key:` in the tracker sub-section of the CLAUDE.md at `claudeMdPath`. */
345	function subsectionValue(claudeMdPath: string, adapter: WorkspaceAdapterKey, key: string): string | undefined {
346	  return subsectionValueIn(readFileSync(claudeMdPath, "utf-8"), adapter, key);
347	}
348	
349	/** The `url` of the `.mcp.json` entry `name` under `root`. */
350	function mcpEntryUrl(root: string, name: string | undefined): Input<string> {
351	  const servers = readMcpServers(root);
352	  if (!servers.ok) return servers;
353	  if (name === undefined || name === "") return failed(`${join(root, "CLAUDE.md")} declares no mcp_server`);
354	  const entry = servers.value[name];
355	  if (entry === undefined) {
356	    return failed(`mcp_server ${name} names no entry in ${join(root, ".mcp.json")} (entries: ${Object.keys(servers.value).join(", ") || "none"})`);
357	  }
358	  if (!isObject(entry) || typeof entry.url !== "string") return failed(`${join(root, ".mcp.json")} entry ${name} has no string url`);
359	  return { ok: true, value: entry.url };
360	}
