390	/**
391	 * Refuse a run that has no binding to move (`mode: none`, no section, or a
392	 * mode that differs from the one passed), else route it: resume, declare, or
393	 * the rows.
394	 */
395	export function routeRepoint(args: RepointArgs): Route {
396	  const claudeMd = join(args.projectRoot, "CLAUDE.md");
397	  const context = `projectRoot=${args.projectRoot}, mode=${args.mode}, newProject=${args.newProject}`;
398	  const section = readTaskTrackingSection(claudeMd);
399	  if (Object.keys(section).length === 0) {
400	    throw new RepointRefusal(
401	      "Refusing: CLAUDE.md has no `## Task Tracking` section — there is no tracker binding to re-point.",
402	      "creating a binding is fresh setup, not a repoint: run /dev-process-toolkit:setup instead.",
403	      `${context}, section=missing`,
404	    );
405	  }
406	  const mode = section["mode"] ?? "";
407	  if (mode === "" || mode === "none") {
408	    throw new RepointRefusal(
409	      "Refusing: `## Task Tracking` is in `mode: none` — there is no tracker binding to re-point.",
410	      "binding a tracker is fresh setup, not a repoint: run /dev-process-toolkit:setup to choose a tracker mode.",
411	      `${context}, declared_mode=${mode === "" ? "absent" : mode}`,
412	    );
413	  }
414	  if (mode !== args.mode) {
415	    throw new RepointRefusal(
416	      `Refusing: CLAUDE.md declares \`mode: ${mode}\`, not the \`${args.mode}\` this run names — a repoint never changes the tracker mode.`,
417	      `pass the declared mode, or switch trackers through /dev-process-toolkit:setup --migrate.`,
418	      `${context}, declared_mode=${mode}`,
419	    );
420	  }
421	
422	  let binding: Input<WorkspaceBinding>;
423	  try {
424	    binding = { ok: true, value: readWorkspaceBinding(claudeMd, args.mode) };
425	  } catch (e) {
426	    binding = failed(firstLine(e));
427	  }
428	  // A refused declaration still names its project: read the line the reader read.
429	  const project = binding.ok ? binding.value.project : subsectionValue(claudeMd, args.mode, "project");
430	  if (project === undefined || project === DEFERRED) return { kind: "resume" };
431	  if (project === args.newProject) return { kind: "declare" };
432	  return { kind: "rows", oldProject: project, binding };
433	}
