441	/** Probe #25's violation reasons for the tree at `root`, joined; `undefined` when it reports none. */
442	async function probe25Violations(root: string): Promise<string | undefined> {
443	  const report = await runTaskTrackingWorkspaceBindingPresentProbe(root);
444	  if (report.violations.length === 0) return undefined;
445	  return report.violations.map((v) => v.reason).join("; ");
