448	/** Row 2: probe #25 in process here and at each peer, then each peer's project and tag. */
449	async function decideRow2(args: RepointArgs, binding: Input<WorkspaceBinding>, peers: Input<string>[]): Promise<RowResult> {
450	  const own = await probe25Violations(args.projectRoot);
451	  if (own !== undefined) return row(2, "REFUSE", `probe #25 reports: ${own}`);
452	  if (!binding.ok) return row(2, "REFUSE", binding.reason);
453	  const tag = binding.value.repoTag;
454	  if (tag === undefined) return row(2, "REFUSE", "the target is shared and this repository declares no repo_tag");
455	  for (const peer of peers) {
456	    if (!peer.ok) return row(2, "REFUSE", peer.reason);
457	    const path = peer.value;
458	    const theirs = await probe25Violations(path);
459	    if (theirs !== undefined) return row(2, "REFUSE", peerRefusal(path, `reports probe #25 violations: ${theirs}`, "That peer's own operator repairs its binding"));
460	    let pb: WorkspaceBinding;
461	    try {
462	      pb = readWorkspaceBinding(join(path, "CLAUDE.md"), args.mode);
463	    } catch (e) {
464	      return row(2, "REFUSE", peerRefusal(path, `has an unreadable binding: ${firstLine(e)}`, "That peer's own operator repairs it"));
465	    }
466	    if (pb.project !== args.newProject) {
467	      return row(2, "REFUSE", peerRefusal(path, `binds project ${pb.project ?? "(none)"}, not ${args.newProject}`, `Repoint this repository to the project that peer binds, or have that peer's operator repoint it to ${args.newProject}`));
468	    }
469	    if (pb.repoTag === undefined) return row(2, "REFUSE", peerRefusal(path, "declares no repo_tag", "That peer is not bootstrapped for a shared container: its own operator declares a repo_tag there"));
470	    if (pb.repoTag === tag) return row(2, "REFUSE", peerRefusal(path, `declares the same repo_tag ${tag}, which no two repositories in one container may share`, "Change THIS repository's repo_tag to one nothing else uses"));
471	  }
472	  return row(2, "PASS", peers.length === 0 ? "peers=0 (not checked)" : `peers=${peers.length}, each bound to ${args.newProject} under a distinct tag`);
473	}
