475	/**
476	 * Row 3 (Jira): `jira_issue_type` declared, offered by `--issue-types` (the
477	 * measured getJiraProjectIssueTypesMetadata answer, proven whole), and the
478	 * same at every peer.
479	 */
480	function decideRow3(args: RepointArgs, peers: Input<string>[]): RowResult {
481	  const types = readMeasuredList("--issue-types", args.issueTypes, "jira:getJiraProjectIssueTypesMetadata", "name");
482	  if (!types.ok) return row(3, "REFUSE", types.reason);
483	  const own = subsectionValue(join(args.projectRoot, "CLAUDE.md"), "jira", "jira_issue_type");
484	  if (own === undefined) return row(3, "REFUSE", "this repository declares no jira_issue_type");
485	  if (!types.value.includes(own)) {
486	    return row(3, "REFUSE", `jira_issue_type ${own} is not offered by ${args.newProject} (--issue-types lists ${types.value.join(", ")})`);
487	  }
488	  for (const peer of peers) {
489	    if (!peer.ok) return row(3, "REFUSE", peer.reason);
490	    const theirs = subsectionValue(join(peer.value, "CLAUDE.md"), "jira", "jira_issue_type");
491	    if (theirs !== own) {
492	      return row(
493	        3,
494	        "REFUSE",
495	        theirs === undefined
496	          ? peerRefusal(peer.value, `declares no jira_issue_type, and this repository declares ${own}`, "That peer is not bootstrapped for this shared space: its own operator declares it")
497	          : peerRefusal(peer.value, `declares jira_issue_type ${theirs}, and this repository declares ${own}`, `Set THIS repository's jira_issue_type to ${theirs} if the peer is right, or have that peer's operator change theirs`),
498	      );
499	    }
500	  }
501	  return row(3, "PASS", `jira_issue_type ${own} is offered by ${args.newProject}${peers.length > 0 ? " and declared by every peer" : ""}`);
502	}
