504	/** Row 5: `mcp_server` names an entry in `.mcp.json`; each peer's entry points at the same URL. */
505	function decideRow5(args: RepointArgs, peers: Input<string>[]): RowResult {
506	  const ownName = readTaskTrackingSection(join(args.projectRoot, "CLAUDE.md"))["mcp_server"];
507	  const own = mcpEntryUrl(args.projectRoot, ownName);
508	  if (!own.ok) return row(5, "REFUSE", own.reason);
509	  const spellings = new Set([ownName!]);
510	  for (const peer of peers) {
511	    if (!peer.ok) return row(5, "REFUSE", peer.reason);
512	    const theirName = readTaskTrackingSection(join(peer.value, "CLAUDE.md"))["mcp_server"];
513	    const theirs = mcpEntryUrl(peer.value, theirName);
514	    if (!theirs.ok) return row(5, "REFUSE", peerRefusal(peer.value, `has an unreadable mcp entry: ${theirs.reason}`, "That peer's own operator repairs it"));
515	    if (theirs.value !== own.value) {
516	      return row(5, "REFUSE", peerRefusal(peer.value, `has its ${theirName} entry pointing at ${theirs.value}, not ${own.value}`, "Point THIS repository's entry at that URL if the peer is right, or have that peer's operator change theirs"));
517	    }
518	    spellings.add(theirName!);
519	  }
520	  const names = [...spellings];
521	  return row(
522	    5,
523	    "PASS",
524	    `one server ${own.value}${names.length > 1 ? ` under ${names.length} spellings: ${names.join(", ")}` : ` as ${names[0]}`}`,
525	  );
526	}
