528	/** Where a spec is live, for a row 7 line: nothing when this checkout's own tree holds it, else every source. */
529	function whereLive(root: string, sources: readonly string[]): string {
530	  const own = new Set([`worktree ${resolve(root)}`, `worktree ${realpathOr(root)}`]);
531	  if (sources.some((src) => own.has(src))) return "";
532	  return ` (on ${sources.join(", ")})`;
