543	/**
544	 * Row 7: no active plan or FR is left in the old container. Each active plan's
545	 * container is resolved through `resolveAttachTarget` over the `--containers`
546	 * listing (the attach front door's read-only provider); an Epic-keyed token
547	 * outside the new project's Epic-token prefix is an old-project container.
548	 * Active FRs bound to an unresolved plan are named with it. Jira: an active FR
549	 * whose tracker key belongs to another project refuses. The two Jira checks
550	 * are probe #25's key-prefix leg's own (`epicTokenOutside`,
551	 * `foreignJiraKeyProject`), so the probe and this row cannot disagree.
552	 */
553	async function decideRow7(args: RepointArgs, listing: ReadListing): Promise<RowResult> {
554	  // Every source the repository holds work in (M_685ff6 review): a plan or FR
555	  // active on an unmerged branch, a second worktree or a remote-tracking ref
556	  // keeps creating in the old project after the flip, so it refuses too. A
557	  // read failure refuses — never read as "no active work".
558	  let specs: ActiveSpecsRead;
559	  try {
560	    specs = await readActiveSpecsFromGit(args.projectRoot);
561	  } catch (e) {
562	    return row(7, "REFUSE", `the repository's git state cannot be read (${firstLine(e)}), so active work on other branches or worktrees is unknown`);
563	  }
564	  const frs = specs.frs.map((f) => {
565	    const fm = parseFrontmatter(f.body, { lenient: true });
566	    const milestone = typeof fm["milestone"] === "string" ? (fm["milestone"] as string).trim() : "";
567	    return { id: f.name, milestone, jiraKey: activeJiraKeyOf(f.body), where: whereLive(args.projectRoot, f.sources) };
568	  });
569	  const provider = listingProvider(args.mode, listing);
570	  const newPrefix = args.mode === "jira" ? epicTokenPrefix(args.newProject) : undefined;
571	  const stranded: string[] = [];
572	  for (const spec of specs.plans) {
573	    const plan = { token: spec.name, where: whereLive(args.projectRoot, spec.sources) };
574	    let why: string | undefined;
575	    if (newPrefix !== undefined && epicTokenOutside(plan.token, newPrefix)) {
576	      why = `its container is outside ${args.newProject}`;
577	    } else {
578	      let name: string | undefined;
579	      const heading = parsePlanHeading(spec.body);
580	      if (heading === null) {
581	        why = `has no milestone heading to resolve (expected \`## ${plan.token} — <title>\`)`;
582	      } else {
583	        name = heading;
584	      }
585	      if (name !== undefined) {
586	        try {
587	          await resolveAttachTarget(provider, args.newProject, name, { sleep: async () => {} });
588	        } catch (e) {
589	          why = `resolves to no container in --containers (${firstLine(e)})`;
590	        }
591	      }
592	    }
593	    if (why === undefined) continue;
594	    const bound = frs.filter((f) => f.milestone === plan.token).map((f) => `${f.id}${f.where}`);
595	    stranded.push(`plan ${plan.token}${plan.where} ${why}${bound.length > 0 ? `; active FRs ${bound.join(", ")}` : ""}`);
596	  }
597	  if (args.mode === "jira") {
598	    for (const fr of frs) {
599	      if (fr.jiraKey !== undefined && foreignJiraKeyProject(fr.jiraKey, args.newProject) !== undefined) {
600	        stranded.push(`active FR ${fr.id}${fr.where} is keyed ${fr.jiraKey}, not ${args.newProject}`);
601	      }
602	    }
603	  }
604	  if (stranded.length > 0) {
605	    return row(7, "REFUSE", `active work left in the old container: ${stranded.map(oneLine).join("; ")}`);
606	  }
607	  return row(7, "PASS", `every active plan resolves in --containers (${listing.rowKeys.length} rows); no active FR is keyed outside ${args.newProject}`);
608	}
