620	/**
621	 * `--statuses`: Linear the measured list_issue_statuses answer — a BARE array,
622	 * the whole list (read by `tracker_answer.ts`); Jira a
623	 * `{ statuses: [{ name }], isLast: true }` wrapper around an answer that IS
624	 * fetchable and should be FETCHED rather than typed.
625	 *
626	 * This comment used to say no Atlassian MCP tool lists a project's statuses.
627	 * That was wrong, and wrong in a way that cost a live leg: `adapters/jira.md`
628	 * declares `list_project_statuses: true`, `tracker_config_proposal.ts` consumes
629	 * that declaration, and two paths are specified there — `allowedValues`
630	 * introspection for company-managed projects and `getTransitionsForJiraIssue`
631	 * → `to.name` for team-managed ones. A child reading the old sentence built the
632	 * listing by hand, and a hand-built gate input reads as fabricated evidence.
633	 *
634	 * Its COMPLETENESS is a different claim and is still asserted, never proven:
635	 * no tracker proves a listing is the whole listing, so `isLast` stays the
636	 * session's word here exactly as it was (see COMPLETENESS_ASSERTED_MARKER).
637	 * Fetching the contents did not close that, and nothing below changed.
638	 */
639	function readStatuses(args: RepointArgs): Input<{ names: string[]; from: AssertedInput }> {
640	  if (args.mode === "linear") {
641	    const m = readMeasuredList("--statuses", args.statuses, "linear:list_issue_statuses", "name");
642	    return m.ok ? { ok: true, value: { names: m.value, from: "statuses" } } : m;
643	  }
644	  const json = readJson("--statuses", args.statuses);
645	  if (!json.ok) return json;
646	  const label = `--statuses ${args.statuses}`;
647	  const o = json.value as Record<string, unknown>;
648	  // BOTH documented Jira shapes are accepted, because both are what the tracker
649	  // actually returns and the session must not have to bridge them by hand.
650	  // `adapters/jira.md` names two paths: `getJiraIssueTypeMetaWithFields`
651	  // `allowedValues` for a company-managed project, and
652	  // `getTransitionsForJiraIssue` -> `to.name` for a team-managed one. The second
653	  // answers `{ transitions: [{ to: { name } }] }`, which carries no `statuses`
654	  // array and no `isLast`.
655	  //
656	  // Live leg 5 (2026-09-24) aborted at step 2 on exactly that: the child fetched
657	  // the documented answer, this function rejected its shape, and the only way
658	  // past was to reshape a fetched file — which the skill's own rule 2 forbids.
659	  // A guard with no legal path causes the failure it exists to prevent, and this
660	  // was the second instance of that class in one milestone. The projection now
661	  // lives HERE, in one tested place, instead of in twenty-six prompts.
662	  if (Array.isArray(o.transitions)) {
663	    const names: string[] = [];
664	    for (const row of o.transitions) {
665	      const to = isObject(row) ? row.to : undefined;
666	      const name = isObject(to) ? to.name : undefined;
667	      if (typeof name !== "string" || name.trim() === "") {
668	        return failed(`${label} is a transitions answer whose rows do not all carry a \`to.name\`; save the raw getTransitionsForJiraIssue answer verbatim.`);
669	      }
670	      if (!names.includes(name)) names.push(name);
671	    }
672	    if (names.length === 0) return failed(`${label} is a transitions answer with no transitions; a status list cannot be derived from it.`);
673	    // No `notLastPage` check: a transitions answer carries no paging and is
674	    // partial by construction, which the caller records rather than pretends away.
675	    return { ok: true, value: { names, from: "statuses:transitions" } };
676	  }
677	  const rows = namedRows(label, o, "statuses", "name");
678	  if (!rows.ok) return rows;
679	  const last = notLastPage(label, o);
680	  return last ?? { ok: true, value: { names: rows.value, from: "statuses" } };
681	}
