683	/** Mark a row that relied on an asserted-complete input: the marker on its line, the input on the row. */
684	function assertedRow(r: RowResult, input: AssertedInput): RowResult {
685	  return { ...r, reason: `${r.reason} ${COMPLETENESS_ASSERTED_MARKER}`, asserted: [input] };
