688	/** Row 4: the tracker config covers the new project's statuses; the row carries the config's status snapshot. */
689	function decideRow4(args: RepointArgs): RowResult {
690	  const statuses = readStatuses(args);
691	  const config = readConfigStatuses(args.projectRoot);
692	  if (!statuses.ok) return row(4, "REFUSE", statuses.reason);
693	  const names = statuses.value.names;
694	  // From here the row relies on the status list: asserted in Jira, proven in
695	  // Linear. The ASSERTED INPUT carries WHICH Jira shape it came from, because a
696	  // full listing and a one-issue transitions subset are different epistemic
697	  // states and one marker for both launders the weaker into the stronger. Row 4
698	  // refuses on a status the config LACKS, so a shorter list is easier to pass.
699	  const mark = (r: RowResult): RowResult => (args.mode === "jira" ? assertedRow(r, statuses.value.from) : r);
700	  if (!config.ok) return mark(row(4, "REFUSE", `${config.reason}; statuses missing: ${names.join(", ")}`));
701	  const missing = names.filter((s) => !config.value.includes(s));
702	  const r4 =
703	    missing.length > 0
704	      ? row(4, "REFUSE", `specs/tracker-config.yaml lacks ${args.newProject} statuses: ${missing.join(", ")}`)
705	      : row(4, "PASS", `config statuses ${config.value.join(", ")} cover ${args.newProject}'s ${names.join(", ")}`);
706	  return { ...mark(r4), statusSnapshot: [...config.value] };
