713	function decideRow6(args: RepointArgs, labels: Input<string[]> | undefined, containers: Input<ReadListing>): RowResult {
714	  let taken: Set<string>;
715	  let key: (p: PlanFile) => string;
716	  if (labels !== undefined) {
717	    if (!labels.ok) return row(6, "REFUSE", labels.reason);
718	    taken = new Set(labels.value);
719	    key = (p) => milestoneLabel(p.token);
720	  } else {
721	    if (!containers.ok) return row(6, "REFUSE", containers.reason);
722	    // A full list_milestones window proves nothing about the milestones past
723	    // it (the shared reader's completeness, via readListingFile): a collision
724	    // there would be unseen, so the row cannot pass on it.
725	    if (!containers.value.complete) {
726	      return row(6, "REFUSE", `--containers holds ${containers.value.rowKeys.length} milestones — a full list_milestones window, which proves nothing past it — so no collision can be ruled out`);
727	    }
728	    taken = new Set((containers.value.linearRows ?? []).map((r) => r.name));
729	    key = (p) => {
730	      try {
