736	  }
737	  const collide = numericPlans(args.projectRoot, false).filter((p) => taken.has(key(p)));
738	  const overlap = numericPlans(args.projectRoot, true).filter((p) => taken.has(key(p))).length;
739	  // The Jira label list is hand-assembled: the row relies on its asserted completeness.
740	  const mark = (r: RowResult): RowResult => (labels !== undefined ? assertedRow(r, "labels") : r);
741	  if (collide.length > 0) {
