747	/**
748	 * Decide rows 1 to 7 from the parsed inputs and the repository tree. Each row
749	 * reads its own inputs first and refuses on any it cannot read.
750	 */
751	export async function decideRows(args: RepointArgs, route: Extract<Route, { kind: "rows" }>): Promise<RowResult[]> {
752	  const results: RowResult[] = [];
753	  const peers = args.peers.map(readPeer);
754	  const containers = readContainers(args);
755	  const labels = args.mode === "jira" ? readLabels(args.labels) : undefined;
756	
757	  // Shared-ness: a declared tag, a listed container, a listed label (Jira), or a named peer.
758	  // A listing that cannot be read cannot prove the target empty, so it counts as shared.
759	  const binding = route.binding;
760	  const empties: string[] = [];
761	  let shared = args.peers.length > 0 || !binding.ok || binding.value.repoTag !== undefined;
762	  if (!containers.ok || containers.value.rowKeys.length > 0) shared = true;
763	  else empties.push("--containers lists 0 rows");
764	  if (labels !== undefined) {
765	    if (!labels.ok || labels.value.length > 0) shared = true;
766	    else empties.push("--labels lists 0 rows");
767	  }
768	  const unshared = `target not shared: ${[...empties, "no --peer", "no repo_tag"].join(", ")}`;
769	
770	  // Row 1 — the new project is visible.
771	  results.push(decideRow1(args));
772	
773	  // Row 2 — probe #25 green here and at every peer; a shared target carries a tag;
774	  // every peer binds the new project under a distinct tag.
775	  if (!shared) results.push(row(2, "NOT-APPLICABLE", unshared));
776	  else results.push(await decideRow2(args, binding, peers));
777	
778	  // Row 3 — the issue type (Jira only, shared targets only).
779	  if (args.mode === "linear") results.push(row(3, "NOT-APPLICABLE", "Linear has no issue-type override"));
780	  else if (!shared) results.push(row(3, "NOT-APPLICABLE", unshared));
781	  else results.push(decideRow3(args, peers));
782	
783	  // Row 4 — the tracker config and the new project's statuses.
784	  results.push(decideRow4(args));
785	
786	  // Row 5 — one server: mcp_server names an entry here, and every peer's entry has the same URL.
787	  results.push(decideRow5(args, peers));
788	
789	  // Row 6 — milestone collisions (Jira: --labels; Linear: --containers).
790	  results.push(decideRow6(args, labels, containers));
791	
792	  // Row 7 — the old container.
793	  if (!containers.ok) results.push(row(7, "REFUSE", containers.reason));
794	  else results.push(await decideRow7(args, containers.value));
795	
796	  return results;
797	}
