849	/** Run git through the shared runner; stdout, or the reason it failed. */
850	function gitRead(cwd: string, args: string[], input?: string): Input<Buffer> {
851	  let proc;
852	  try {
853	    proc = runGit(cwd, args, { timeoutMs: GIT_TIMEOUT_MS, ...(input !== undefined ? { input } : {}) });
854	  } catch (e) {
855	    return failed(`git ${args[0]} failed (${e instanceof Error ? e.message : String(e)})`);
856	  }
857	  if (proc.error) return failed(`git ${args[0]} failed (${proc.error.message})`);
858	  if (proc.status !== 0) return failed(`git ${args[0]} exited ${proc.status ?? "on a signal"} (${proc.stderr.toString("utf-8").trim()})`);
859	  return { ok: true, value: proc.stdout };
860	}
