862	/** Local branches other than the current one whose committed CLAUDE.md still binds `oldProject`. */
863	function staleBranches(root: string, adapter: WorkspaceAdapterKey, oldProject: string): Input<string[]> {
864	  const refs = gitRead(root, ["for-each-ref", "--format=%(HEAD) %(refname)", "refs/heads"]);
865	  if (!refs.ok) return refs;
866	  const names: string[] = [];
867	  for (const line of refs.value.toString("utf-8").split("\n")) {
868	    if (line.length < 3 || line.startsWith("*")) continue; // the branch being repointed is not stale
869	    names.push(line.slice(2).replace(/^refs\/heads\//, ""));
870	  }
871	  if (names.length === 0) return { ok: true, value: [] };
872	  const batch = gitRead(root, ["cat-file", "--batch"], names.map((n) => `refs/heads/${n}:CLAUDE.md\n`).join(""));
873	  if (!batch.ok) return batch;
874	  const out = batch.value;
875	  const stale: string[] = [];
876	  let pos = 0;
877	  for (const name of names) {
878	    const nl = out.indexOf(0x0a, pos);
879	    if (nl < 0) return failed(`git cat-file --batch ended before refs/heads/${name}:CLAUDE.md`);
880	    const header = out.subarray(pos, nl).toString("utf-8").split(" ");
881	    pos = nl + 1;
882	    if (header.length !== 3) continue; // `<object> missing`: the branch has no CLAUDE.md
883	    const size = Number(header[2]);
884	    if (header[1] !== "blob" || !Number.isInteger(size)) {
885	      return failed(`git cat-file --batch answered ${header.join(" ")} for refs/heads/${name}:CLAUDE.md`);
886	    }
887	    const text = out.subarray(pos, pos + size).toString("utf-8");
888	    pos += size + 1;
889	    if (subsectionValueIn(text, adapter, "project") === oldProject) stale.push(name);
890	  }
891	  return { ok: true, value: stale };
892	}
