95	export function normalizeContainerItems(
96	  items: readonly Record<string, unknown>[],
97	  adapter: WorkspaceAdapterKey,
98	  shared = false,
99	): ContainerTicket[] {
100	  return items.map((row) => {
101	    if (adapter === "jira") {
102	      const key = str(row["key"]);
103	      const fields = (row["fields"] ?? {}) as Record<string, unknown>;
104	      if (key === undefined) refuseField("key", undefined);
105	      const title = str(fields["summary"]);
106	      if (title === undefined) refuseField("summary", key);
107	      const type = fields["issuetype"] as { name?: unknown; hierarchyLevel?: unknown } | undefined;
108	      if (!type || str(type.name) === undefined) refuseField("issuetype", key);
109	      if (shared) requireShared(fields, ["labels", "description", "creator"], key);
110	      const level = typeof type.hierarchyLevel === "number" ? type.hierarchyLevel : 0;
111	      const description = typeof fields["description"] === "string" ? (fields["description"] as string) : "";
112	      return {
113	        key,
114	        title,
115	        labels: labelsOf(fields["labels"]),
116	        isContainer: type.name === "Epic" || level > 0,
117	        project: str((fields["project"] as { key?: unknown } | undefined)?.key) ?? null,
118	        creator: nameOf(fields["creator"]),
119	        hasBackLink: BACK_LINK_RE.test(description),
120	      };
