124	    const key = trackerItemKey("linear", row) ?? undefined;
125	    if (key === undefined) refuseField("id", undefined);
126	    const title = str(row["title"]);
127	    if (title === undefined) refuseField("title", key);
128	    if (shared) requireShared(row, ["labels", "description", "createdBy"], key);
129	    const description = typeof row["description"] === "string" ? (row["description"] as string) : "";
