131	      key,
132	      title,
133	      labels: labelsOf(row["labels"]),
134	      // Linear milestones are not issues: nothing on a Linear page is a container.
135	      isContainer: false,
136	      project: nameOf(row["project"]),
137	      creator: nameOf(row["createdBy"]),
138	      hasBackLink: BACK_LINK_RE.test(description),
139	    };
140	  });
