// per VIOLATION and the report takes the maximum across its rows, so one
// advisory never masks a hard failure and an advisory-only run stays green.
//
// THREE ARMS RUN THAT CLASSIFIER — `mode: none`, `mode: jira` and
// `mode: linear` — over one machinery and three epochs. The arms diverge on
// exactly two things: the boundary instant (`MINT_EPOCH`, `JIRA_EPIC_EPOCH`,
// `LINEAR_TRACKER_KEY_EPOCH`) and what a `fresh` plan should have been instead
// — a re-minted `M_<6-char>` under `none`, an Epic-derived `M_<KEY>` under
// `jira`, a front-door-minted `M_<6-hex>` under `linear`. Those per-mode parts
// live in one `SequentialProvenanceArm` record each; the step from a
// classification to a row is written once, in `sequentialProvenanceViolation`,
// so the arms cannot drift apart in shape. Their `undecidable` advisories go
// one step further: a severed object store admits ONE remedy whatever the
// tracker mode, so that row is built by `undecidableProvenanceViolation` with
// each arm passing in only its verdict sentence and its epoch.
//
// SIBLING MODULE, NOT AN EXTENSION of `identity_mode_conditional.ts`. That
// module documents a deliberate scope-isolation boundary (FR-only walk, zero
// runtime dep on `ulid.ts`); widening it to plan files would violate the

// and either refuses the typed number with the full breakdown or reports the
// next free one.
//
//   bun run adapters/_shared/src/next_free_milestone_number.ts specs M101
//   Refusing: milestone M101 is already claimed — ...
//
//   bun run adapters/_shared/src/next_free_milestone_number.ts specs M999
//   typed=M999
//   verdict=free
//   next-free=M102
//
// The tracker and branch legs need injected scanners this door cannot build,
// so both report `(none)` here — the file-system and CHANGELOG legs are the
// ones a command line can measure. `import.meta.main` is false on import, so
// the module stays side-effect free for its importers.
if (import.meta.main) {
  const specsDir = process.argv[2];
  const typedToken = process.argv[3];
  const typedNumber = typedToken?.match(new RegExp(`^${NUMERIC_MILESTONE_NUMBER_SOURCE}$`))?.[1];

  if (specsDir === undefined || typedNumber === undefined) {
    console.error(
      [
        "Refusing: to check a typed milestone identity without a specs directory and an `M<N>` token.",
        "Remedy: bun run adapters/_shared/src/next_free_milestone_number.ts <specsDir> <typed-M-token>",
        `Context: mode=milestone-number-allocation, phase=explicit-M-token-check, argv=${specsDir === undefined ? "incomplete" : `malformed-token:${typedToken}`}`,
      ].join("\n"),
    );
    process.exitCode = 1;
  } else {
    // STE-608 AC-STE-608.13 — a NEW numeric milestone is refused in tracker
    // mode: its identity comes from the tracker, through the decision front
    // door. The mode is read from the CLAUDE.md beside <specsDir>; a file that
    // cannot be read, or a `mode:` that is none of the three, refuses rather
    // than falling through to `mode: none`. A missing file or section is
    // `mode: none`, as everywhere else `readTaskTrackingSection` is used.
    const claudeMdPath = join(specsDir, "..", "CLAUDE.md");
    const typedId = `M${typedNumber}`;
    let mode: string | undefined;
    let modeRefusal: string | null = null;
    try {
      mode = readTaskTrackingSection(claudeMdPath)["mode"];
    } catch (e) {
      modeRefusal = [
        `Refusing: to check typed milestone ${typedId} — the CLAUDE.md beside the specs directory could not be read, so the tracker mode is unknown.`,
        `Remedy: make ${claudeMdPath} a readable file declaring \`## Task Tracking\` → \`mode:\`, then re-run.`,
        `Context: mode=milestone-number-allocation, phase=explicit-M-token-check, typed=${typedId}, claude_md=${claudeMdPath}, error=${e instanceof Error ? e.message : String(e)}`,
      ].join("\n");
    }
    if (modeRefusal === null && mode !== undefined && mode !== "none" && mode !== "jira" && mode !== "linear") {
      modeRefusal = [
        `Refusing: to check typed milestone ${typedId} — \`## Task Tracking\` declares a malformed mode ${JSON.stringify(mode)}; expected none, jira or linear.`,
        `Remedy: set \`mode:\` in ${claudeMdPath} to one of none, jira, linear, then re-run.`,
        `Context: mode=milestone-number-allocation, phase=explicit-M-token-check, typed=${typedId}, tracker_mode=${JSON.stringify(mode)}`,
      ].join("\n");
    }
    if (modeRefusal === null && (mode === "jira" || mode === "linear")) {
      modeRefusal = [
        `Refusing: typed milestone ${typedId} under mode: ${mode} — a new numeric milestone is not minted in tracker mode; its identity comes from the tracker.`,
        `Remedy: run the decision front door \`bun run adapters/_shared/src/resolve_milestone_identity.ts\` to mint (or join) the milestone through the ${mode} tracker instead of typing an M<N>.`,
        `Context: mode=milestone-number-allocation, phase=explicit-M-token-check, typed=${typedId}, tracker_mode=${mode}`,
      ].join("\n");
    }
    if (modeRefusal !== null) {
      console.error(modeRefusal);
      process.exitCode = 1;
    } else {
      const typed = Number(typedNumber);
      const availability = await nextFreeMilestoneNumber(
        specsDir,
        join(specsDir, "..", "CHANGELOG.md"),
      );
      const refusal = explicitMilestoneCollisionRefusal(typed, availability);
      if (refusal !== null) {
        console.error(refusal);
        process.exitCode = 1;

  }

  return {
    mode,
    // Maximum across the rows, so one advisory never masks a hard failure and
    // an advisory-only run does not fail the gate. With zero rows there is no
    // maximum to take, so the report falls back to the module's declared
    // default — the value the gate has always read for an empty report.
    severity:
      violations.length === 0
        ? PLAN_IDENTITY_MODE_CONDITIONAL_SEVERITY
        : violations.some((v) => v.severity === "error")
          ? "error"
          : "warning",
    violations,
  };
}

// STE-616 AC-STE-616.20 — probe #73's command-line front door. Prints the
// report as one JSON line on stdout and exits 1 when any row has error
// severity, else 0; a usage error exits 2. `import.meta.main` is false on
// import, so the module stays side-effect free for its importers.
if (import.meta.main) {
  const projectRoot = process.argv[2];
  if (projectRoot === undefined) {
    console.error("usage: plan_identity_mode_conditional.ts <projectRoot>");
    process.exit(2);
  }
  const report = await runPlanIdentityModeConditionalProbe(projectRoot);
  console.log(JSON.stringify(report));
  process.exit(report.violations.some((v) => v.severity === "error") ? 1 : 0);
}
